-- ============================================
-- LUMA — Thème 11 (Festival) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"friend": "ton ami(e)", "friend_text": "message texte"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend_text", "text": "(Text) We''re near the food trucks, but it''s SO crowded, can you find us?", "text_fr": "(Texto) On est près des camions food, mais c''est TELLEMENT bondé, tu peux nous trouver ?", "choices": [{"text": "(Reply) Which food truck exactly? There are like ten here.", "text_fr": "(Réponds) Quel camion exactement ? Il y en a genre dix ici.", "next": "n2"}, {"text": "(Reply) I''ll head that way now, can you send a pin location?", "text_fr": "(Réponds) Je me dirige par là maintenant, tu peux envoyer une localisation ?", "next": "n2b"}]}, "n2": {"speaker": "friend_text", "text": "(Text) The taco one! With the big rainbow sign, can''t miss it.", "text_fr": "(Texto) Celui des tacos ! Avec le grand panneau arc-en-ciel, impossible à louper.", "choices": [{"text": "(Reply) Got it, heading there now!", "text_fr": "(Réponds) Compris, j''y vais maintenant !", "next": "n3"}]}, "n2b": {"speaker": "friend_text", "text": "(Text) Sending it now, give me a sec!", "text_fr": "(Texto) Je l''envoie maintenant, laisse-moi une seconde !", "choices": [{"text": "(Wait for the location, scanning the crowd meanwhile.)", "text_fr": "(Attends la localisation, en scannant la foule pendant ce temps.)", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(You push through the crowd, scanning for familiar faces.)", "text_fr": "(Vous vous frayez un chemin dans la foule, en cherchant des visages familiers.)", "choices": [{"text": "(Spot the rainbow sign and head straight for it.)", "text_fr": "(Repère le panneau arc-en-ciel et dirige-toi droit vers lui.)", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "(Waves enthusiastically) There you are! We were starting to worry!", "text_fr": "(Fait signe avec enthousiasme) Te voilà ! On commençait à s''inquiéter !", "choices": [{"text": "Sorry, this crowd is insane! Glad I found you all.", "text_fr": "Désolé, cette foule est folle ! Content de vous avoir tous trouvés.", "next": "end_reunited"}]}, "end_reunited": {"speaker": "friend", "text": "No worries, you''re here now! Let''s grab tacos and catch the next set together.", "text_fr": "T''inquiète, t''es là maintenant ! Prenons des tacos et allons voir le prochain concert ensemble.", "end": true, "ending_label": "Groupe retrouvé dans la foule 🎪👥"}}}'::jsonb, is_playable = true
where title = 'Retrouver des amis dans la foule'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"seller": "le vendeur de billets"}, "start_node": "n1", "nodes": {"n1": {"speaker": "seller", "text": "Sorry, we''re basically sold out for tonight''s show. Just a few VIP spots left.", "text_fr": "Désolé, on est pratiquement complets pour le concert ce soir. Juste quelques places VIP restantes.", "choices": [{"text": "How much for a VIP ticket? I really don''t want to miss this.", "text_fr": "Combien pour un billet VIP ? Je veux vraiment pas rater ça.", "next": "n2"}, {"text": "Is there any waitlist in case regular tickets open up?", "text_fr": "Il y a une liste d''attente au cas où des billets normaux se libèrent ?", "next": "n2b"}]}, "n2": {"speaker": "seller", "text": "VIP is $150, but it includes backstage access and free drinks all night.", "text_fr": "Le VIP c''est 150$, mais ça inclut l''accès backstage et des boissons gratuites toute la soirée.", "choices": [{"text": "That''s steep, but honestly, worth it for tonight. I''ll take it.", "text_fr": "C''est cher, mais honnêtement, ça vaut le coup pour ce soir. Je le prends.", "next": "n3"}, {"text": "Could you do $120? That''s really pushing my budget.", "text_fr": "Vous pourriez faire 120$ ? Ça pousse vraiment mon budget.", "next": "n3b"}]}, "n2b": {"speaker": "seller", "text": "There''s a small chance — people sometimes return tickets last minute. Want to wait?", "text_fr": "Il y a une petite chance — les gens rendent parfois des billets à la dernière minute. Vous voulez attendre ?", "choices": [{"text": "Sure, I''ll wait a bit and see what happens.", "text_fr": "Bien sûr, je vais attendre un peu et voir ce qui se passe.", "next": "n3c"}]}, "n3": {"speaker": "seller", "text": "Great choice, here''s your VIP wristband. Enjoy the show!", "text_fr": "Excellent choix, voici votre bracelet VIP. Profitez du spectacle !", "choices": [{"text": "Thank you so much, I really appreciate it.", "text_fr": "Merci beaucoup, j''apprécie vraiment.", "next": "end_vip"}]}, "n3b": {"speaker": "seller", "text": "(Considers) Alright, $130, final offer, since it''s getting late anyway.", "text_fr": "(Réfléchit) Bon, 130$, dernière offre, vu qu''il se fait tard de toute façon.", "choices": [{"text": "Deal! Thank you for working with me.", "text_fr": "Marché conclu ! Merci de faire un effort.", "next": "end_vip"}]}, "n3c": {"speaker": "seller", "text": "(Ten minutes later) Actually, someone just returned a regular ticket! Want it?", "text_fr": "(Dix minutes plus tard) En fait, quelqu''un vient de rendre un billet normal ! Vous le voulez ?", "choices": [{"text": "Yes! Absolutely, thank you for holding on for me.", "text_fr": "Oui ! Absolument, merci d''avoir attendu pour moi.", "next": "end_lucky"}]}, "end_vip": {"speaker": "seller", "text": "Have an amazing night, VIP treatment awaits!", "text_fr": "Passez une soirée incroyable, le traitement VIP vous attend !", "end": true, "ending_label": "Billet VIP obtenu à la dernière minute 🎫✨"}, "end_lucky": {"speaker": "seller", "text": "Lucky timing! Enjoy the show, it''s going to be a great one.", "text_fr": "Timing chanceux ! Profitez du spectacle, ça va être excellent.", "end": true, "ending_label": "Billet trouvé grâce à la patience 🎫🍀"}}}'::jsonb, is_playable = true
where title = 'Acheter un billet à la dernière minute'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
